// Generates lib/app/theme/tokens.dart from design/tokens.json.
//
// Run from the repo root after changing tokens.json:
//   dart run tool/gen_tokens.dart
//
// The output is passed through `dart format`.
// test/app/theme/tokens_sync_test.dart fails if the generated file is stale.

import 'dart:convert';
import 'dart:io';

const tokensJsonPath = 'design/tokens.json';
const tokensDartPath = 'lib/app/theme/tokens.dart';

void main() {
  final json = File(tokensJsonPath).readAsStringSync();
  File(tokensDartPath).writeAsStringSync(generateTokensDart(json));
  final format = Process.runSync('dart', [
    'format',
    tokensDartPath,
  ], runInShell: true);
  if (format.exitCode != 0) {
    stderr.write(format.stderr);
    exit(format.exitCode);
  }
  stdout.writeln('Wrote $tokensDartPath');
}

/// Turns the contents of `design/tokens.json` into Dart source.
String generateTokensDart(String tokensJson) {
  final root = jsonDecode(tokensJson) as Map<String, dynamic>;
  final out = StringBuffer()
    ..writeln('// GENERATED by tool/gen_tokens.dart from design/tokens.json.')
    ..writeln('// Do not edit by hand. Run `dart run tool/gen_tokens.dart`.')
    ..writeln()
    ..writeln("import 'package:flutter/painting.dart';")
    ..writeln();

  _writeColors(out, root['color'] as Map<String, dynamic>);
  _writeType(out, root['type'] as Map<String, dynamic>);
  _writeDimensions(out, 'TokenSpace', root['spacing'] as Map<String, dynamic>);
  _writeDimensions(out, 'TokenRadius', root['radius'] as Map<String, dynamic>);
  _writeDimensions(out, 'TokenSize', root['size'] as Map<String, dynamic>);
  return out.toString();
}

void _writeColors(StringBuffer out, Map<String, dynamic> color) {
  final tokens = (color['tokens'] as List<dynamic>)
      .cast<Map<String, dynamic>>();
  final byName = {for (final t in tokens) t['name'] as String: t['value']};

  String resolve(Object? value, String theme) {
    if (value is Map<String, dynamic>) return resolve(value[theme], theme);
    final s = value as String;
    final ref = RegExp(r'^\{(.+)\}$').firstMatch(s);
    if (ref != null) return resolve(byName[ref.group(1)], theme);
    return s;
  }

  out
    ..writeln('/// Colour tokens for one theme.')
    ..writeln('class TokenColors {')
    ..writeln('  const TokenColors({');
  for (final t in tokens) {
    out.writeln('    required this.${_camel(t['name'] as String)},');
  }
  out
    ..writeln('  });')
    ..writeln();
  for (final t in tokens) {
    out
      ..writeln('  /// ${t['usage']}')
      ..writeln('  final Color ${_camel(t['name'] as String)};');
  }
  for (final theme in ['light', 'dark']) {
    out
      ..writeln()
      ..writeln('  static const $theme = TokenColors(');
    for (final t in tokens) {
      final hex = resolve(
        t['value'],
        theme,
      ).replaceFirst('#', '').toUpperCase();
      out.writeln('    ${_camel(t['name'] as String)}: Color(0xFF$hex),');
    }
    out.writeln('  );');
  }
  out
    ..writeln('}')
    ..writeln();
}

void _writeType(StringBuffer out, Map<String, dynamic> type) {
  final families = type['families'] as Map<String, dynamic>;
  final primary = (families['sans'] as String).split(',').first.trim();
  out
    ..writeln(
      '/// One type style from the token file. Sizes are logical pixels.',
    )
    ..writeln('class TokenTextStyle {')
    ..writeln('  const TokenTextStyle({')
    ..writeln('    required this.fontSize,')
    ..writeln('    required this.lineHeight,')
    ..writeln('    required this.fontWeight,')
    ..writeln('    this.letterSpacing = 0,')
    ..writeln('  });')
    ..writeln()
    ..writeln('  final double fontSize;')
    ..writeln('  final double lineHeight;')
    ..writeln('  final FontWeight fontWeight;')
    ..writeln('  final double letterSpacing;')
    ..writeln('}')
    ..writeln()
    ..writeln('abstract final class TokenType {')
    ..writeln("  static const fontFamily = '$primary';");
  for (final group
      in (type['groups'] as List<dynamic>).cast<Map<String, dynamic>>()) {
    for (final s
        in (group['styles'] as List<dynamic>).cast<Map<String, dynamic>>()) {
      final spacing = s['letterSpacing'] as String?;
      out
        ..writeln()
        ..writeln('  /// ${s['usage']}')
        ..writeln(
          '  static const ${_camel(s['name'] as String)} = TokenTextStyle(',
        )
        ..writeln('    fontSize: ${_px(s['fontSize'] as String)},')
        ..writeln('    lineHeight: ${_px(s['lineHeight'] as String)},')
        ..writeln('    fontWeight: FontWeight.w${s['fontWeight']},');
      if (spacing != null) out.writeln('    letterSpacing: ${_px(spacing)},');
      out.writeln('  );');
    }
  }
  out
    ..writeln('}')
    ..writeln();
}

void _writeDimensions(
  StringBuffer out,
  String className,
  Map<String, dynamic> group,
) {
  out.writeln('abstract final class $className {');
  final tokens = (group['tokens'] as List<dynamic>)
      .cast<Map<String, dynamic>>();
  for (final t in tokens) {
    out
      ..writeln('  /// ${t['usage']}')
      ..writeln(
        '  static const double ${_camel(t['name'] as String)} = ${_px(t['value'] as String)};',
      );
  }
  out.writeln('}');
  if (className != 'TokenSize') out.writeln();
}

/// `surface-raised` -> `surfaceRaised`, `space-1` -> `space1`.
String _camel(String name) {
  final parts = name.split('-');
  return parts.first +
      parts.skip(1).map((p) => p[0].toUpperCase() + p.substring(1)).join();
}

/// `"16px"` -> `16`, `"-0.5px"` -> `-0.5`.
String _px(String value) {
  final n = double.parse(value.replaceAll('px', ''));
  return n == n.roundToDouble() ? n.toInt().toString() : n.toString();
}
